static TreeNode* build_tree_from_json(const char* s) {
    size_t cap = 1024, count = 0;
    int* vals = (int*)malloc(cap * sizeof(int));
    unsigned char* present = (unsigned char*)malloc(cap * sizeof(unsigned char));

    size_t i = 0, len = strlen(s);
    while (i < len) {
        while (i < len && (s[i] == '[' || s[i] == ']' || s[i] == ',' ||
                           isspace((unsigned char)s[i]))) {
            ++i;
        }
        if (i >= len) break;

        if (strncmp(s + i, "null", 4) == 0) {
            if (count == cap) {
                cap *= 2;
                vals = (int*)realloc(vals, cap * sizeof(int));
                present = (unsigned char*)realloc(present, cap * sizeof(unsigned char));
            }
            vals[count] = 0;
            present[count] = 0;
            ++count;
            i += 4;
        } else if (s[i] == '-' || isdigit((unsigned char)s[i])) {
            char* end = NULL;
            long v = strtol(s + i, &end, 10);
            if (count == cap) {
                cap *= 2;
                vals = (int*)realloc(vals, cap * sizeof(int));
                present = (unsigned char*)realloc(present, cap * sizeof(unsigned char));
            }
            vals[count] = (int)v;
            present[count] = 1;
            ++count;
            i = (size_t)(end - s);
        } else {
            ++i;
        }
    }

    TreeNode* root = NULL;
    if (count > 0 && present[0]) {
        root = new_node(vals[0]);
        TreeNode** queue = (TreeNode**)malloc(count * sizeof(TreeNode*));
        size_t head = 0, tail = 0, idx = 1;
        queue[tail++] = root;

        while (head < tail && idx < count) {
            TreeNode* node = queue[head++];

            if (idx < count && present[idx]) {
                node->left = new_node(vals[idx]);
                queue[tail++] = node->left;
            }
            ++idx;

            if (idx < count && present[idx]) {
                node->right = new_node(vals[idx]);
                queue[tail++] = node->right;
            }
            ++idx;
        }
        free(queue);
    }

    free(vals);
    free(present);
    return root;
}

static Pair rob_helper(TreeNode* root) {
    if (!root) return (Pair){0, 0};
    Pair left = rob_helper(root->left);
    Pair right = rob_helper(root->right);

    Pair result;
    result.take = root->val + left.skip + right.skip;
    result.skip = (left.take > left.skip ? left.take : left.skip)
                + (right.take > right.skip ? right.take : right.skip);
    return result;
}

int rob(TreeNode* root) {
    Pair result = rob_helper(root);
    return result.take > result.skip ? result.take : result.skip;
}

