class Solution {
public:
    int rob(TreeNode* root) {
        if (!root) return 0;

        unordered_map<TreeNode*, array<int, 2>> dp;
        vector<pair<TreeNode*, bool>> st;
        st.push_back({root, false});

        while (!st.empty()) {
            auto [node, visited] = st.back();
            st.pop_back();

            if (!node) continue;

            if (!visited) {
                st.push_back({node, true});
                if (node->right) st.push_back({node->right, false});
                if (node->left) st.push_back({node->left, false});
            } else {
                array<int, 2> left = node->left ? dp[node->left] : array<int, 2>{0, 0};
                array<int, 2> right = node->right ? dp[node->right] : array<int, 2>{0, 0};
                int take = node->val + left[1] + right[1];
                int skip = max(left[0], left[1]) + max(right[0], right[1]);
                dp[node] = {take, skip};
            }
        }

        auto result = dp[root];
        return max(result[0], result[1]);
    }
};

