class Solution {
    public int rob(TreeNode root) {
        if (root == null) return 0;

        class Frame {
            TreeNode node;
            boolean visited;
            Frame(TreeNode node, boolean visited) {
                this.node = node;
                this.visited = visited;
            }
        }

        IdentityHashMap<TreeNode, int[]> dp = new IdentityHashMap<>();
        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(root, false));

        while (!stack.isEmpty()) {
            Frame frame = stack.pop();
            TreeNode node = frame.node;

            if (!frame.visited) {
                stack.push(new Frame(node, true));
                if (node.right != null) stack.push(new Frame(node.right, false));
                if (node.left != null) stack.push(new Frame(node.left, false));
            } else {
                int[] left = node.left == null ? new int[]{0, 0} : dp.get(node.left);
                int[] right = node.right == null ? new int[]{0, 0} : dp.get(node.right);
                int take = node.val + left[1] + right[1];
                int skip = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
                dp.put(node, new int[]{take, skip});
            }
        }

        int[] rootDp = dp.get(root);
        return Math.max(rootDp[0], rootDp[1]);
    }
}

