vector<string> tokensFromInput(const string& line) {
    vector<string> tokens;
    for (size_t i = 0; i < line.size();) {
        if (line.compare(i, 4, "null") == 0) {
            tokens.push_back("null");
            i += 4;
        } else if (line[i] == '-' || isdigit(static_cast<unsigned char>(line[i]))) {
            size_t j = i + 1;
            while (j < line.size() && isdigit(static_cast<unsigned char>(line[j]))) ++j;
            tokens.push_back(line.substr(i, j - i));
            i = j;
        } else {
            ++i;
        }
    }
    return tokens;
}

TreeNode* buildTree(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;

    TreeNode* root = new TreeNode(stoi(tokens[0]));
    vector<TreeNode*> queue{root};
    size_t head = 0, i = 1;

    while (head < queue.size() && i < tokens.size()) {
        TreeNode* node = queue[head++];

        if (i < tokens.size() && tokens[i] != "null") {
            node->left = new TreeNode(stoi(tokens[i]));
            queue.push_back(node->left);
        }
        ++i;

        if (i < tokens.size() && tokens[i] != "null") {
            node->right = new TreeNode(stoi(tokens[i]));
            queue.push_back(node->right);
        }
        ++i;
    }
    return root;
}

void deleteTree(TreeNode* root) {
    if (!root) return;
    vector<TreeNode*> st{root};
    while (!st.empty()) {
        TreeNode* node = st.back();
        st.pop_back();
        if (node->left) st.push_back(node->left);
        if (node->right) st.push_back(node->right);
        delete node;
    }
}

